SET DEFINE OFF

DELETE FROM TBL_LOAN;
DELETE FROM TBL_BOOK;
DELETE FROM TBL_STUDENT;

BEGIN EXECUTE IMMEDIATE 'DROP SEQUENCE SEQ_LOAN'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2289 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP SEQUENCE SEQ_BOOK'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2289 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'DROP SEQUENCE SEQ_STUDENT'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2289 THEN RAISE; END IF; END;
/
CREATE SEQUENCE SEQ_STUDENT START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE SEQ_BOOK    START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE SEQ_LOAN    START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;




COMMIT;

SELECT b.BOOK_ID, b.TITLE, b.TOTAL_QTY, b.AVAIL_QTY,
b.TOTAL_QTY - COUNT(CASE WHEN l.RETURN_YN = 'N' THEN 1 END) AS EXPECTED_AVAIL
FROM TBL_BOOK b
LEFT JOIN TBL_LOAN l ON l.BOOK_ID = b.BOOK_ID
GROUP BY b.BOOK_ID, b.TITLE, b.TOTAL_QTY, b.AVAIL_QTY
HAVING b.AVAIL_QTY <> b.TOTAL_QTY - COUNT(CASE WHEN l.RETURN_YN = 'N' THEN 1 END);

SELECT (SELECT COUNT(*) FROM TBL_BOOK) AS BOOKS, (SELECT COUNT(*) FROM TBL_STUDENT) AS STUDENTS, (SELECT COUNT(*) FROM TBL_LOAN) AS LOANS, (SELECT COUNT(*) FROM TBL_LOAN WHERE RETURN_YN = 'N') AS UNRETURNED, (SELECT COUNT(*) FROM TBL_LOAN WHERE RETURN_YN = 'N' AND DUE_DATE < TRUNC(SYSDATE)) AS OVERDUE FROM dual;

SELECT l.LOAN_ID, s.STUDENT_NAME, b.TITLE, TO_CHAR(l.LOAN_DATE, 'YYYY-MM-DD') AS LOAN_DATE, TO_CHAR(l.DUE_DATE, 'YYYY-MM-DD') AS DUE_DATE,
CASE WHEN l.RETURN_YN = 'Y' THEN '반납완료' WHEN l.DUE_DATE < TRUNC(SYSDATE) THEN '연체' ELSE '미반납' END AS STATUS
FROM TBL_LOAN l
JOIN TBL_STUDENT s ON l.STUDENT_ID = s.STUDENT_ID
JOIN TBL_BOOK b ON l.BOOK_ID = b.BOOK_ID
ORDER BY l.LOAN_ID;
